from pathlib import Path
import zipfile, html

root=Path(__file__).parent
z=zipfile.ZipFile(root.parent/'lab1zip.zip')
(root/'images').mkdir(exist_ok=True)
(root/'images/workspace.svg').write_bytes(z.read('lab1/images/workspace.svg'))
old={name:z.read('lab1/'+name+'.html').decode('utf-8') for name in ['article','experience']}
links=[('index.html','Start'),('gallery.html','Projekty'),('experience.html','Doświadczenie'),('article.html','Notatnik'),('contact.html','Kontakt')]
def page(name,title,content):
    content=content.replace('Jan Kowalski','Szymon Firek')
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==name else '')+f'>{label}</a>' for url,label in links)
    (root/name).write_text(f'''<!DOCTYPE html>
<html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Portfolio Szymona Firka. Projekty internetowe, doświadczenie i notatki o tworzeniu stron."><title>{title} · Szymon Firek</title><link rel="icon" href="images/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css"><script src="navigation.js" defer></script></head>
<body class="{'home-page' if name == 'index.html' else ''}"><a class="skip" href="#main">Przejdź do treści</a><header class="site-header"><div class="container header-inner"><a class="brand" href="index.html"><span class="brand-icon">sf.</span> Szymon Firek<span class="brand-sub"> / portfolio</span></a><nav aria-label="Menu glowne">{nav}</nav></div></header><nav class="floating-nav" aria-label="Menu podczas przewijania" inert>{nav}</nav><main id="main" class="container">{content}</main><footer class="site-footer"><div class="container footer-inner"><a class="brand" href="index.html"><span class="brand-icon">sf.</span> Szymon Firek</a><p>Małe kroki. Przemyślane strony.</p><span>© 2026 · HTML & CSS</span><a href="#main">Do góry ↑</a></div></footer></body></html>''',encoding='utf-8')

def heading(kicker,title,desc): return f'<div class="page-heading"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></div>'
def card(n,title,desc,kind): return f'<article class="project-card"><a class="project-image {kind}" href="gallery.html#projekt-{n}"><img src="images/project-{n}.svg" alt="{desc}" width="720" height="480"><span class="image-arrow" aria-hidden="true">↗</span></a><div class="project-meta"><span>0{n} / {kind.upper()}</span><span>2026</span></div><h3><a href="gallery.html#projekt-{n}">{title} <span aria-hidden="true">↗</span></a></h3><p>{desc}</p></article>'

page('index.html','Start','''<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> CZEŚĆ, JESTEM SZYMON</p><h1>Pomysły zamieniam<br>w <em>czytelne strony.</em></h1><p class="lead">Poznaję świat frontendu i buduję swoje miejsce w sieci. Łączę prosty kod, dobry design i ciekawość tego, co można zrobić lepiej.</p><div class="actions"><a class="button" href="gallery.html">Zobacz moje projekty <span>↗</span></a><a class="text-link" href="contact.html">Porozmawiajmy <span>→</span></a></div><div class="hero-tags"><span>HTML5</span><span>CSS3</span><span>Responsive design</span></div></div><div class="hero-art"><div class="art-top"><span><i></i><i></i><i></i></span><span>workspace / 01</span></div><img src="images/workspace.svg" alt="Laptop z kodem na ekranie na uporządkowanym biurku" width="600" height="300"><div class="art-bottom"><span>Od pomysłu do pierwszego &lt;div&gt;</span><span>✳</span></div><span class="art-note">Zbudowane z ciekawości.</span></div></section>
<section class="intro-strip"><p>PROSTOTA W FORMIE.<br><strong>Uważność w szczegółach.</strong></p><p>To portfolio jest moim warsztatem. Zbieram tu projekty, doświadczenia i notatki z nauki tworzenia stron internetowych.</p><a class="text-link" href="experience.html">Poznaj mnie lepiej ↗</a></section>
<section class="section"><div class="section-heading"><div><p class="eyebrow">WYBRANE REALIZACJE</p><h2>Od nauki do praktyki<span class="accent">.</span></h2></div><a class="text-link" href="gallery.html">Wszystkie projekty ↗</a></div><div class="projects-grid">'''+card(1,'Pierwsza strona internetowa','Osobista przestrzeń w sieci. Semantyczny HTML i przejrzysty układ.','web')+card(2,'Doświadczenie w dobrym układzie','Czytelna prezentacja edukacji, umiejętności i kolejnych kroków.','layout')+'''</div></section><section class="contact-banner"><div><p class="eyebrow">MASZ POMYSŁ?</p><h2>Zróbmy z niego coś dobrego.</h2><p>Projekt, pytanie, a może po prostu wymiana doświadczeń?</p></div><a class="button" href="contact.html">Napisz do mnie ↗</a></section>''')

